const body = $input.first().json.body;
const required = ['product_name', 'launch_date', 'product_type'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const launchDate = new Date(body.launch_date);
if (isNaN(launchDate)) return [{ json: { valid: false, error: 'launch_date must be a valid date (YYYY-MM-DD)' } }];
const today = new Date();
today.setHours(0,0,0,0);
const daysUntilLaunch = Math.floor((launchDate - today) / 86400000);
const productTypes = ['saas', 'mobile_app', 'physical_product', 'digital_download', 'marketplace_listing', 'api_product', 'content_product', 'service_launch', 'feature_release'];
const productType = productTypes.includes(body.product_type) ? body.product_type : 'saas';
const channels = Array.isArray(body.launch_channels)
  ? body.launch_channels
  : (body.launch_channels || '').split(',').map(c => c.trim()).filter(Boolean);
return [{ json: {
  valid: true,
  productName: body.product_name.trim(),
  productType,
  launchDate: body.launch_date,
  daysUntilLaunch,
  launchChannels: channels,
  teamSize: parseInt(body.team_size) || null,
  existingAudience: body.existing_audience === true || body.existing_audience === 'true',
  targetMarket: (body.target_market || '').slice(0, 300),
  keyFeatures: (body.key_features || '').slice(0, 500),
  launchGoal: (body.launch_goal || '').slice(0, 300),
  knownRisks: (body.known_risks || '').slice(0, 400),
  previousLaunches: body.previous_launches || '',
  replyEmail: body.reply_email || null,
  requestedAt: new Date().toISOString()
} }];

values.content:
Generate a product launch checklist.

Product: {{ $json.productName }}
Type: {{ $json.productType.replace(/_/g,' ') }}
Launch date: {{ $json.launchDate }}
Days until launch: {{ $json.daysUntilLaunch }}
Launch channels: {{ $json.launchChannels.join(', ') || 'not specified' }}
Team size: {{ $json.teamSize || 'not specified' }}
Existing audience: {{ $json.existingAudience }}
Target market: {{ $json.targetMarket || 'not specified' }}
Key features: {{ $json.keyFeatures || 'not specified' }}
Launch goal: {{ $json.launchGoal || 'not specified' }}
Known risks: {{ $json.knownRisks || 'none specified' }}
Previous launches: {{ $json.previousLaunches || 'not specified' }}

Return this JSON:
{
  "launch_readiness_assessment": "2-3 sentences on overall readiness given the timeline and product type — be honest if the timeline is tight",
  "critical_path_items": ["the 3-5 items that are most likely to delay or derail the launch if not done — be specific to this product type"],
  "phases": [
    {
      "phase": "T-30 to T-14 days",
      "label": "Foundation",
      "items": [
        {
          "task": "specific, actionable task",
          "owner": "product | marketing | engineering | design | legal | support | exec | all",
          "is_blocker": true or false,
          "notes": "why this matters or how to do it — 1-2 sentences",
          "estimated_hours": 4
        }
      ]
    }
  ],
  "launch_day_runbook": [
    {
      "time": "e.g. 6:00 AM",
      "task": "specific launch day action",
      "owner": "team",
      "if_fails": "contingency if this step fails or is delayed"
    }
  ],
  "post_launch_monitoring": {
    "metrics_to_watch": ["specific metrics for first 48 hours"],
    "alert_thresholds": ["specific thresholds that should trigger action"],
    "day_1_tasks": ["actions for the first day post-launch"],
    "week_1_tasks": ["actions for the first week post-launch"]
  },
  "commonly_overlooked": ["3-5 things teams forget for this specific product type and launch channel combination"],
  "go_no_go_criteria": ["5-7 specific conditions that must be true on launch day — concrete, verifiable"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let checklist;
try { checklist = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
checklist._meta = { productName: input.productName, productType: input.productType, launchDate: input.launchDate, daysUntilLaunch: input.daysUntilLaunch, launchChannels: input.launchChannels, replyEmail: input.replyEmail };
return [{ json: checklist }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const ownerColors = {product:'#7c3aed', marketing:'#2563eb', engineering:'#16a34a', design:'#d97706', legal:'#dc2626', support:'#0891b2', exec:'#374151', all:'#6b7280'};

const totalTasks = (c.phases||[]).reduce((s,p) => s + (p.items||[]).length, 0);
const blockerCount = (c.phases||[]).reduce((s,p) => s + (p.items||[]).filter(i=>i.is_blocker).length, 0);

const phaseBlocks = (c.phases||[]).map(phase => {
  const items = (phase.items||[]).map(item => {
    const oc = ownerColors[item.owner] || '#6b7280';
    return `<div style="display:flex;gap:10px;padding:9px 0;border-bottom:1px solid #f3f4f6;align-items:flex-start">
      <input type="checkbox" style="margin-top:3px;flex-shrink:0">
      <div style="flex:1">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:3px">
          <span style="font-size:14px;font-weight:${item.is_blocker ? '700' : '500'};color:${item.is_blocker ? '#1a1a1a' : '#374151'}">${esc(item.task)}</span>
          ${item.is_blocker ? '<span style="background:#fef2f2;color:#dc2626;font-size:10px;font-weight:700;padding:1px 7px;border-radius:8px">BLOCKER</span>' : ''}
        </div>
        <div style="display:flex;gap:8px;align-items:center">
          <span style="background:${oc}22;color:${oc};font-size:11px;padding:2px 8px;border-radius:8px;font-weight:600">${esc(item.owner)}</span>
          ${item.estimated_hours ? `<span style="font-size:11px;color:#9ca3af">~${item.estimated_hours}h</span>` : ''}
        </div>
        ${item.notes ? `<div style="font-size:12px;color:#6b7280;margin-top:4px">${esc(item.notes)}</div>` : ''}
      </div>
    </div>`;
  }).join('');
  return `<div style="margin-bottom:24px">
    <div style="background:#f8faff;border-left:4px solid #2563eb;padding:10px 16px;margin-bottom:10px;border-radius:0 6px 6px 0">
      <div style="font-size:12px;color:#9ca3af;text-transform:uppercase;letter-spacing:0.4px">${esc(phase.phase)}</div>
      <div style="font-size:16px;font-weight:700;color:#1e3a8a">${esc(phase.label)}</div>
    </div>
    ${items}
  </div>`;
}).join('');

const runbookRows = (c.launch_day_runbook||[]).map(r => `
  <tr style="border-bottom:1px solid #f3f4f6">
    <td style="padding:8px 12px;font-size:13px;font-weight:600;color:#374151;white-space:nowrap">${esc(r.time)}</td>
    <td style="padding:8px 12px;font-size:13px">${esc(r.task)}</td>
    <td style="padding:8px 12px;font-size:12px;color:#6b7280">${esc(r.owner)}</td>
    <td style="padding:8px 12px;font-size:12px;color:#d97706">${esc(r.if_fails||'—')}</td>
  </tr>`).join('');

const goNogo = (c.go_no_go_criteria||[]).map(g => `<div style="font-size:14px;padding:7px 0;border-bottom:1px solid #f0fdf4;color:#166534">☐ ${esc(g)}</div>`).join('');
const overlooked = (c.commonly_overlooked||[]).map(o => `<li style="font-size:14px;margin-bottom:7px;line-height:1.5;color:#374151">${esc(o)}</li>`).join('');
const critical = (c.critical_path_items||[]).map(p => `<div style="font-size:14px;padding:6px 0;border-bottom:1px solid #fecaca;color:#7f1d1d">⚡ ${esc(p)}</div>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f5f5f0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:720px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:5px">Launch Checklist · ${esc(m.productType.replace(/_/g,' '))}</div>
    <div style="font-size:19px;font-weight:700">${esc(m.productName)}</div>
    <div style="font-size:13px;color:#9ca3af;margin-top:4px">Launch: ${esc(m.launchDate)} · ${m.daysUntilLaunch > 0 ? m.daysUntilLaunch + ' days away' : m.daysUntilLaunch === 0 ? 'TODAY' : Math.abs(m.daysUntilLaunch) + ' days ago'} · ${totalTasks} tasks · ${blockerCount} blockers</div>
  </div>
  <div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:none">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:6px">Readiness assessment</div>
    <p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(c.launch_readiness_assessment)}</p>
  </div>
  ${critical ? `<div style="background:#fef2f2;padding:14px 28px;border:1px solid #fecaca">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#b91c1c;margin-bottom:8px">Critical path — don't miss these</div>
    ${critical}
  </div>` : ''}
  <div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:14px">Checklist by phase</div>
    ${phaseBlocks}
  </div>
  ${runbookRows ? `<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f5f5f0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#9ca3af;margin-bottom:10px">Launch day runbook</div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af">
        <th style="padding:7px 12px;text-align:left">Time</th>
        <th style="padding:7px 12px;text-align:left">Task</th>
        <th style="padding:7px 12px;text-align:left">Owner</th>
        <th style="padding:7px 12px;text-align:left">If it fails</th>
      </tr></thead>
      <tbody>${runbookRows}</tbody>
    </table>
  </div>` : ''}
  ${goNogo ? `<div style="background:#f0fdf4;padding:14px 28px;border:1px solid #bbf7d0">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#15803d;margin-bottom:8px">Go / No-go criteria</div>
    ${goNogo}
  </div>` : ''}
  ${overlooked ? `<div style="background:#fffbeb;padding:14px 28px;border:1px solid #fde68a">
    <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#92400e;margin-bottom:8px">Commonly overlooked for this type</div>
    <ul style="padding-left:18px;margin:0">${overlooked}</ul>
  </div>` : ''}
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:12px 28px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Launch Checklist Agent · ${esc(m.productName)} · ${esc(m.launchDate)}
  </div>
</div></body></html>`;

return [{ json: { html, replyEmail: m.replyEmail, productName: m.productName, launchDate: m.launchDate, totalTasks, blockerCount, checklist: c } }];
